            "normas.pdf_button": "DESCARGAR PDF",
            "normas.section_heading": "NORMAS OFICIALES",
            "normas.intro": "De obligado cumplimiento para todos los participantes. La inscripción en cualquier evento implica la aceptación íntegra de este reglamento.",
            "normas.index_title": "Ir a la sección",
            "normas.index.seguridad": "1. Seguridad",
            "normas.index.replicas": "2. Réplicas y equipo",
